const policyRows = () => ORACLE.filter((r) => r[2] === 'policy');

function matcher(): (p: string) => boolean {
  const policy = new SentinelWatchPolicy() as unknown as { isIgnored?: (p: string) => boolean };
  assert.equal(typeof policy.isIgnored, 'function', 'SentinelWatchPolicy.isIgnored is missing');
  return (p) => policy.isIgnored!(p);
}

suite('SentinelWatchPolicy ignore matcher equals chokidar 3 (C2 T1)', () => {
  for (const root of ROOTS) {
    test(`root ${root}: every policy row gives chokidar ${ORACLE_VERSION}'s answer`, () => {
      const isIgnored = matcher();
      const rows = policyRows().filter((r) => underRoot(r[0], root));
      assert.ok(rows.length > 0, 'no oracle rows for this root');
      const wrong = rows.filter((r) => isIgnored(r[0]) !== r[1]).map((r) => `${r[0]} expected ${r[1]}`);
      assert.deepEqual(wrong, [], `${wrong.length} of ${rows.length} rows differ`);
    });
  }

  test('the oracle holds both answers, and its atomic rows are exactly chokidar DOT_RE paths', () => {
    const rows = policyRows();
    const ignored = rows.filter((r) => r[1]).length;
    assert.ok(ignored > 0 && rows.length - ignored > 0, `ignored ${ignored}, watched ${rows.length - ignored}`);
    for (const r of ORACLE) assert.equal(DOT_RE.test(r[0]), r[2] === 'atomic', r[0]);
    for (const r of ORACLE.filter((x) => x[2] === 'atomic')) assert.equal(r[1], true, r[0]);
  });

  test('cross-check: the frozen oracle equals a live chokidar 3.6.0', async function () {
    // src/test/sentinel -> out/test/sentinel at run time; the extension root is three levels up.
    const ext = path.resolve(__dirname, '..', '..', '..');
    const explicit = path.join(ext, 'node_modules', '@vscode', 'test-cli', 'node_modules', 'chokidar');
    const root = path.join(ext, 'node_modules', 'chokidar');
    const versionOf = (dir: string) => (fs.existsSync(path.join(dir, 'package.json')) ? JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8')).version as string : null);
    const dir = versionOf(explicit)?.startsWith('3.') ? explicit : versionOf(root)?.startsWith('3.') ? root : null;
    if (!dir) {
      console.log(`[ignore-equivalence] cross-check skipped: no chokidar 3 at ${explicit} or ${root}; ${ORACLE.length} rows unchecked`);
      this.skip();
      return;
    }
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const chokidar3 = require(dir) as { FSWatcher: new (o: Record<string, unknown>) => { _isIgnored: (p: string) => boolean; close: () => Promise<void> } };
    const watcher = new chokidar3.FSWatcher({ ignored: new SentinelWatchPolicy().getIgnorePatterns(), atomic: true, persistent: false });
    try {
      const wrong = ORACLE.filter((r) => watcher._isIgnored(r[0]) !== r[1]).map((r) => r[0]);
      console.log(`[ignore-equivalence] cross-check ran: chokidar ${versionOf(dir)} at ${dir}; ${ORACLE.length} rows, ${wrong.length} differ`);
      assert.deepEqual(wrong, []);
    } finally {
      await watcher.close();
    }
  });
});

suite('SentinelWatchPolicy ignore pattern compiler (C2 T2)', () => {
  const compile = () => {
    const fn = (policyModule as unknown as { compileIgnorePattern?: (g: string) => unknown }).compileIgnorePattern;
    assert.equal(typeof fn, 'function', 'compileIgnorePattern is missing');
    return fn!;
  };

  test('every pattern from getIgnorePatterns() compiles', () => {
    const fn = compile();
    const patterns = new SentinelWatchPolicy().getIgnorePatterns();
    assert.ok(patterns.length > 0);
    for (const p of patterns) assert.doesNotThrow(() => fn(p), p);
  });

  for (const shape of ['**/{a,b}/**', '**/a*/**', '**/a[b]/**', 'src/**', '**/*.{ts,js}', '!**/x/**']) {
    test(`refuses the unsupported shape ${shape}`, () => {
      const fn = compile();
      assert.throws(() => fn(shape), /unsupported ignore pattern/);
    });
  }
});
